    [Fact] public async Task Two_orders_cannot_use_same_active_table() { var (s, _, b, t) = Setup(true); await s.CreateAsync(new CreateOrderRequest(b.Id, OrderType.DineIn, t.Id, null, null, null, null, null), C); await FluentActions.Awaiting(() => s.CreateAsync(new CreateOrderRequest(b.Id, OrderType.DineIn, t.Id, null, null, null, null, null), C)).Should().ThrowAsync<ConflictException>(); }
    [Fact] public async Task Order_number_is_not_client_supplied() { typeof(CreateOrderRequest).GetProperty("OrderNumber").Should().BeNull(); }
    [Fact] public async Task Update_item_preserves_new_note() { var (s, _, b, _) = Setup(true); var order = await s.CreateAsync(new CreateOrderRequest(b.Id, OrderType.Takeaway, null, null, null, null, null, null), C); var item = await s.AddItemAsync(order.Id, new AddOrderItemRequest(ProductId, null, null, 1, [], null, order.Version), C); (await s.UpdateItemAsync(order.Id, item!.Items.Single().Id, new UpdateOrderItemRequest(ProductId, null, null, 1, [], "updated note", item.Version), C))!.Items.Single().Notes.Should().Be("updated note"); }
    [Fact] public async Task Item_modifier_quantity_is_one_for_selected_option() { var (s, c, b, _) = Setup(true); var g = new ModifierGroup { Name = "T", MaximumSelections = 1 }; var m = new Modifier { ModifierGroupId = g.Id, Name = "x", DefaultPrice = 1 }; c.ModifierGroups.Add(g); c.Modifiers.Add(m); c.ProductModifierGroups.Add(new ProductModifierGroup { ProductId = ProductId, ModifierGroupId = g.Id }); await c.SaveChangesAsync(); var order = await s.CreateAsync(new CreateOrderRequest(b.Id, OrderType.Takeaway, null, null, null, null, null, null), C); var result = await s.AddItemAsync(order.Id, new AddOrderItemRequest(ProductId, null, null, 1, [m.Id], null, order.Version), C); result!.Items.Single().Modifiers.Single().Quantity.Should().Be(1); }
    [Fact] public async Task Order_status_history_keeps_reason() { var (s, _, b, _) = Setup(true); var order = await s.CreateAsync(new CreateOrderRequest(b.Id, OrderType.Takeaway, null, null, null, null, null, null), C); await s.CancelAsync(order.Id, new CancelOrderRequest("customer request", order.Version), C); (await s.GetAsync(order.Id, C))!.Status.Should().Be(OrderStatus.Cancelled); }
    [Fact] public async Task Completed_order_cannot_remove_item() { var (s, _, b, _) = Setup(true); var order = await s.CreateAsync(new CreateOrderRequest(b.Id, OrderType.Takeaway, null, null, null, null, null, null), C); var item = await s.AddItemAsync(order.Id, new AddOrderItemRequest(ProductId, null, null, 1, [], null, order.Version), C); var confirmed = await s.ChangeStatusAsync(order.Id, new ChangeOrderStatusRequest(OrderStatus.Confirmed, null, item!.Version), C); var preparing = await s.ChangeStatusAsync(order.Id, new ChangeOrderStatusRequest(OrderStatus.Preparing, null, confirmed!.Version), C); var ready = await s.ChangeStatusAsync(order.Id, new ChangeOrderStatusRequest(OrderStatus.Ready, null, preparing!.Version), C); var complete = await s.ChangeStatusAsync(order.Id, new ChangeOrderStatusRequest(OrderStatus.Completed, null, ready!.Version), C); await FluentActions.Awaiting(() => s.RemoveItemAsync(order.Id, item.Items.Single().Id, complete!.Version, C)).Should().ThrowAsync<DomainApplicationException>(); }

    private static readonly CancellationToken C = CancellationToken.None;
    private static (OrderManagementService Service, RestaurantDbContext Context, Branch Branch, DiningTable Table) Setup(bool admin)
    {
        var context = new RestaurantDbContext(new DbContextOptionsBuilder<RestaurantDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options); var branch = new Branch { Code = Guid.NewGuid().ToString(), Name = "Main" }; var area = new Area { BranchId = branch.Id, Name = "Ground" }; var table = new DiningTable { BranchId = branch.Id, AreaId = area.Id, TableNumber = "01", Capacity = 4 }; var product = new Product { Sku = Guid.NewGuid().ToString(), Name = "Coffee" }; context.Branches.Add(branch); context.Areas.Add(area); context.DiningTables.Add(table); context.Products.Add(product); context.BranchProducts.Add(new BranchProduct { BranchId = branch.Id, ProductId = product.Id, PriceOverride = 30000 }); context.SaveChanges(); CurrentProductId.Value = product.Id; var service = new OrderManagementService(context, new TestUser(admin), new TestAudit(), new ProductPricingService(context), new ModifierComboService(context, new TestUser(admin), new TestAudit())); return (service, context, branch, table);
    }
    private static readonly AsyncLocal<Guid> CurrentProductId = new();
    private static Guid ProductId => CurrentProductId.Value;
    private sealed class TestUser(bool admin) : ICurrentUserService { public Guid? UserId => null; public string? Username => "test"; public IReadOnlyCollection<string> Roles => []; public IReadOnlyCollection<string> Permissions => []; public Guid? BranchId => null; public bool IsAdministrator => admin; }
    private sealed class TestAudit : IAuditWriter { public Task WriteAsync(string action, string entityType, Guid? entityId, string? actorName, string? ipAddress, CancellationToken cancellationToken) => Task.CompletedTask; }
}